using namespace System.Net

# $sub and $DID are injected by CloudLabs. Sample alerts are learner-created Defender state.
$count=0;$found=$false;$detail='No validation attempt completed.';$plans=@('StorageAccounts','KeyVaults','SqlServers');$expected=@('Storage.Blob_OpenACL.Sensitive','KV.UnusualAccessSuspiciousIP','SQL.DB_PotentialSqlInjection')
function Reply($s,$m){if($s -eq 'Succeeded'){$body=@{Status = "Succeeded";Message = $m}|ConvertTo-Json -Compress}else{$body=@{Status = "Failed";Message = $m}|ConvertTo-Json -Compress};Push-OutputBinding -Name Response -Value ([HttpResponseContext]@{StatusCode=[HttpStatusCode]::OK;Body=$body}) -Clobber}
do{$count++;try{Set-AzContext -Subscription $sub -ErrorAction Stop|Out-Null;$pricing=@(Get-AzSecurityPricing -ErrorAction Stop);foreach($p in $plans){$m=@($pricing|Where-Object{$_.Name-ceq $p});if($m.Count-ne 1 -or $m[0].PricingTier-ne 'Standard'){throw "Plan '$p' is not exactly one Standard pricing record."}};$r=Invoke-AzRestMethod -Path "/subscriptions/$sub/providers/Microsoft.Security/alerts?api-version=2022-01-01" -Method GET -ErrorAction Stop;if([string]::IsNullOrWhiteSpace($r.Content)){throw 'Defender alerts API returned empty content.'};$rows=@(($r.Content|ConvertFrom-Json).value);if($rows.Count-eq 0){throw 'Defender alerts API returned zero rows.'};$types=@($rows|ForEach-Object{$_.properties.alertType});$missing=@($expected|Where-Object{$types-notcontains $_});if($missing.Count){throw "Missing exact sample alert type(s): $($missing -join ', ')."};$found=$true;Reply 'Succeeded' "Subscription '$sub' has all three plans at Standard and required sample alerts: $($expected -join ', ')."}catch{$detail=$_.Exception.Message;Reply 'Failed' "Challenge 3 attempt $count of 3 failed closed: $detail";if($count-lt 3){Start-Sleep -Seconds 10}}}while($count-lt 3 -and -not $found)
if(-not $found){Reply 'Failed' "Challenge 3 failed after 3 attempts. Last observation: $detail"}